import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadTerracottaData(){const e=readFileSync(resolve(__dirname,"../../terracotta-pottery-explorer/terracotta-data.js"),"utf-8");return new Function(e+"\nreturn { TERRACOTTA_INFO, PROCESS_STEPS, REGIONAL_STYLES, GALLERY_IMAGES, REFERENCES };")()}describe("Terracotta Pottery Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadTerracottaData()}),describe("TERRACOTTA_INFO metadata",()=>{it("contains correct Terracotta Pottery attributes and GI tag info",()=>{expect(e.TERRACOTTA_INFO.id).toBe("terracotta-pottery"),expect(e.TERRACOTTA_INFO.title).toContain("Terracotta Pottery"),expect(e.TERRACOTTA_INFO.historicalBackground).toContain("Indus Valley"),expect(e.TERRACOTTA_INFO.materialsUsed).toContain("Alluvial Clay")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.TERRACOTTA_INFO.quickStats)).toBe(!0),expect(e.TERRACOTTA_INFO.quickStats.length).toBe(6)})}),describe("PROCESS_STEPS & REGIONAL_STYLES",()=>{it("contains pottery making steps and regional clay styles",()=>{expect(Array.isArray(e.PROCESS_STEPS)).toBe(!0),expect(e.PROCESS_STEPS.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.REGIONAL_STYLES)).toBe(!0),expect(e.REGIONAL_STYLES.length).toBeGreaterThanOrEqual(4)})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})}),describe("Molela explorer integration",()=>{it("loads the shared Journey module and bookmark button on the Molela page",()=>{const e=readFileSync(resolve(__dirname,"../../molela-clay-art-explorer/index.html"),"utf-8");expect(e).toContain("journey.js"),expect(e).toContain('id="molela-bookmark-btn"')})})});